INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'educator', 'n.', '/ˈedʒukeɪtə(r)/', '教育工作者;教育家', 'Her father was an excellent educator who loved poetry.', '她的父亲是一位热爱诗歌的优秀教育家。', 'Learning for Life', 1, 0, 'senior', 'wordlist', 'elective1', 'U1', 'an excellent educator', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'recite', 'v.', '/rɪˈsaɪt/', '背诵;朗诵', 'As a child, she was often asked to recite poems in front of visitors.', '小时候,她常被要求在客人面前背诵诗歌。', 'Learning for Life', 2, 0, 'senior', 'wordlist', 'elective1', 'U1', 'recite a poem', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'achievement', 'n.', '/əˈtʃiːvmənt/', '成就;成绩;达成', 'Achievement consists in never giving up on your learning.', '成就在于对学习永不放弃。', 'Learning for Life', 3, 0, 'senior', 'wordlist', 'elective1', 'U1', 'a great achievement', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'wisdom', 'n.', '/ˈwɪzdəm/', '智慧;才智', 'The more he studied, the clearer his wisdom became.', '他学得越多,智慧就越清明。', 'Learning for Life', 4, 0, 'senior', 'wordlist', 'elective1', 'U1', 'gain wisdom', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'virtue', 'n.', '/ˈvɜːtʃuː/', '美德;德行;优点', 'Patience is a virtue that every lifelong learner needs.', '耐心是每个终身学习者都需要的美德。', 'Learning for Life', 5, 0, 'senior', 'wordlist', 'elective1', 'U1', 'a virtue', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'process', 'n.', '/ˈprəʊses/', '过程;进程;工序', 'Doing the experiments engaged us in the learning process.', '做实验让我们投入到学习过程之中。', 'Learning for Life', 6, 0, 'senior', 'wordlist', 'elective1', 'U1', 'the learning process', '美音 /ˈprɑːses/', 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'trial', 'n.', '/ˈtraɪəl/', '考验;磨难;试验', 'Speaking in front of others was a great trial for the shy girl.', '在别人面前讲话对这个害羞的女孩是一大考验。', 'Learning for Life', 7, 0, 'senior', 'wordlist', 'elective1', 'U1', 'a great trial', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'struggle', 'n./v.', '/ˈstrʌɡl/', '艰难;奋斗;艰难地做', 'He struggled with reading as a child but taught himself to write.', '他小时候阅读很吃力,但自学会了写字。', 'Learning for Life', 8, 0, 'senior', 'wordlist', 'elective1', 'U1', 'struggle with', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'pursue', 'v.', '/pəˈsjuː/', '追求;从事;继续', 'After the war he went abroad to pursue further studies in physics.', '战后他出国深造,继续研究物理。', 'Learning for Life', 9, 0, 'senior', 'wordlist', 'elective1', 'U1', 'pursue further studies', '美音 /pərˈsuː/', 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'scholarship', 'n.', '/ˈskɒləʃɪp/', '奖学金;学问', 'He worked hard and won a scholarship to a famous university.', '他刻苦努力,赢得了一所名校的奖学金。', 'Learning for Life', 10, 0, 'senior', 'wordlist', 'elective1', 'U1', 'win a scholarship', '美音 /ˈskɑːlərʃɪp/', 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'breakthrough', 'n.', '/ˈbreɪkθruː/', '突破;重大进展', 'His research led to a major breakthrough in battery design.', '他的研究在电池设计上带来了重大突破。', 'Learning for Life', 11, 0, 'senior', 'wordlist', 'elective1', 'U1', 'a major breakthrough', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'laboratory', 'n.', '/ləˈbɒrətri/', '实验室', 'Even at ninety-seven, he still goes to the laboratory every day.', '即便九十七岁,他每天仍去实验室。', 'Learning for Life', 12, 0, 'senior', 'wordlist', 'elective1', 'U1', 'in the laboratory', '美音 /ˈlæbrətɔːri/', 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'experiment', 'n./v.', '/ɪkˈsperɪmənt/', '实验;试验;做实验', 'Darwin helped his brother do many experiments in chemistry.', '达尔文帮哥哥做了许多化学实验。', 'Learning for Life', 13, 0, 'senior', 'wordlist', 'elective1', 'U1', 'do an experiment', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'guidance', 'n.', '/ˈɡaɪdns/', '指导;引导;辅导', 'Under her father''s guidance, Curie developed a taste for poetry.', '在父亲的指导下,居里渐渐爱上了诗歌。', 'Learning for Life', 14, 0, 'senior', 'wordlist', 'elective1', 'U1', 'under the guidance of', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'influence', 'n./v.', '/ˈɪnfluəns/', '影响;影响力;感化', 'Since childhood he had been under the influence of his learned father.', '从小他就一直受到博学父亲的影响。', 'Learning for Life', 15, 0, 'senior', 'wordlist', 'elective1', 'U1', 'under the influence of', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'knowledge', 'n.', '/ˈnɒlɪdʒ/', '知识;学识;了解', 'Real knowledge is to know the extent of one''s ignorance.', '真正的知识是知道自己无知的程度。', 'Learning for Life', 16, 0, 'senior', 'wordlist', 'elective1', 'U1', 'practical knowledge', '美音 /ˈnɑːlɪdʒ/', 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'patient', 'adj.', '/ˈpeɪʃnt/', '有耐心的;能忍耐的', 'His grandfather told him to be patient and practise every day.', '他祖父叫他要有耐心,每天练习。', 'Learning for Life', 17, 0, 'senior', 'wordlist', 'elective1', 'U1', 'be patient', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'cease', 'v.', '/siːs/', '停止;终止', 'The gentleman believes that learning should never cease.', '君子认为学习不应停止。', 'Learning for Life', 18, 0, 'senior', 'wordlist', 'elective1', 'U1', 'never cease', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'thus', 'adv.', '/ðʌs/', '因此;从而;以这种方式', 'He examined himself each day; thus his conduct became faultless.', '他每天反省自己,因此行为没有过错。', 'Learning for Life', 19, 0, 'senior', 'wordlist', 'elective1', 'U1', 'thus', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'conduct', 'n.', '/ˈkɒndʌkt/', '行为;举止', 'Wide study made both his wisdom and his conduct clear.', '广泛的学习使他的智慧和举止都变得清明。', 'Learning for Life', 20, 0, 'senior', 'wordlist', 'elective1', 'U1', 'good conduct', '美音 /ˈkɑːndʌkt/', 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'dignity', 'n.', '/ˈdɪɡnəti/', '尊严;自尊;庄重', 'He learned that everyone has a strong sense of dignity.', '他懂得每个人都有强烈的尊严感。', 'Learning for Life', 21, 0, 'senior', 'wordlist', 'elective1', 'U1', 'a sense of dignity', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'defeat', 'v./n.', '/dɪˈfiːt/', '击败;战胜;失败', 'As a boy, he learned to defeat his opponents without shaming them.', '还是个男孩时,他就学会不羞辱对手地战胜他们。', 'Learning for Life', 22, 0, 'senior', 'wordlist', 'elective1', 'U1', 'defeat an opponent', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'opponent', 'n.', '/əˈpəʊnənt/', '对手;竞争者', 'A good learner treats every opponent with respect.', '好的学习者尊重每一个对手。', 'Learning for Life', 23, 0, 'senior', 'wordlist', 'elective1', 'U1', 'a worthy opponent', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'embarrass', 'v.', '/ɪmˈbærəs/', '使尴尬;使窘迫', 'The donkey threw him off, which embarrassed him in front of his friends.', '驴把他摔了下来,让他在朋友面前很尴尬。', 'Learning for Life', 24, 0, 'senior', 'wordlist', 'elective1', 'U1', 'embarrass someone', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'suffer', 'v.', '/ˈsʌfə(r)/', '遭受;蒙受;受苦', 'To shame another person is to make him suffer a cruel fate.', '羞辱他人就是让他遭受残忍的命运。', 'Learning for Life', 25, 0, 'senior', 'wordlist', 'elective1', 'U1', 'suffer a loss', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'cruel', 'adj.', '/ˈkruːəl/', '残忍的;残酷的', 'He felt it was cruel and unnecessary to shame a beaten rival.', '他觉得羞辱落败的对手既残忍又没必要。', 'Learning for Life', 26, 0, 'senior', 'wordlist', 'elective1', 'U1', 'a cruel fate', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'gather', 'v.', '/ˈɡæðə(r)/', '采集;收集;聚集', 'In the fields he learned to gather wild honey and fruits.', '在田野里他学会了采集野蜂蜜和果子。', 'Learning for Life', 27, 0, 'senior', 'wordlist', 'elective1', 'U1', 'gather wild honey', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'stream', 'n.', '/striːm/', '小溪;小河;一连串', 'Unless you pile up tiny streams, you can never make a river.', '不积小流,无以成江河。', 'Learning for Life', 28, 0, 'senior', 'wordlist', 'elective1', 'U1', 'a clear stream', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'carve', 'v.', '/kɑːv/', '雕刻;刻', 'If you persist without stopping, you can carve metal or stone.', '锲而不舍,金石可镂。', 'Learning for Life', 29, 0, 'senior', 'wordlist', 'elective1', 'U1', 'carve metal or stone', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'pace', 'n.', '/peɪs/', '步;步幅;速度', 'The finest horse cannot travel ten paces in one leap.', '最好的马也不能一跃十步。', 'Learning for Life', 30, 0, 'senior', 'wordlist', 'elective1', 'U1', 'ten paces', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'metal', 'n.', '/ˈmetl/', '金属', 'If metal is put to the grindstone, it can be sharpened.', '金属放到磨石上,就能被磨利。', 'Learning for Life', 31, 0, 'senior', 'wordlist', 'elective1', 'U1', 'sharpen metal', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'press', 'v.', '/pres/', '压;按;施加压力', 'If wood is pressed against a board, it can be made straight.', '木头被压在矫直板上,就能弄直。', 'Learning for Life', 32, 0, 'senior', 'wordlist', 'elective1', 'U1', 'press against', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'distance', 'n.', '/ˈdɪstəns/', '远方;距离;间距', 'He gazed into the distance but saw farther by climbing higher.', '他眺望远方,但爬得更高才看得更远。', 'Learning for Life', 33, 0, 'senior', 'wordlist', 'elective1', 'U1', 'into the distance', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'wave', 'v.', '/weɪv/', '挥手;招手;挥动', 'If you climb high and wave, people can see you from far away.', '登高招手,远处的人也能看见你。', 'Learning for Life', 34, 0, 'senior', 'wordlist', 'elective1', 'U1', 'wave to someone', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'somehow', 'adv.', '/ˈsʌmhaʊ/', '不知怎么地;以某种方式', 'The fact that they worked on chemistry somehow got known at school.', '他们研究化学的事不知怎么在学校传开了。', 'Learning for Life', 35, 0, 'senior', 'wordlist', 'elective1', 'U1', 'somehow', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'practically', 'adv.', '/ˈpræktɪkli/', '实际地;几乎;实事求是地', 'The work showed him practically the meaning of experimental science.', '这项工作切实地向他展示了实验科学的意义。', 'Learning for Life', 36, 0, 'senior', 'wordlist', 'elective1', 'U1', 'show practically', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'honour', 'n.', '/ˈɒnə(r)/', '荣誉;尊敬;荣幸', 'He graduated with honours in mathematics at Yale University.', '他在耶鲁大学以优异成绩获得数学学位。', 'Learning for Life', 37, 0, 'senior', 'wordlist', 'elective1', 'U1', 'receive an honour', '美式拼 honor;美音 /ˈɑːnər/', 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'purchase', 'v./n.', '/ˈpɜːtʃəs/', '购买;采购', 'He raised money to purchase tools for the school laboratory.', '他筹钱为学校实验室购买工具。', 'Learning for Life', 38, 0, 'senior', 'wordlist', 'elective1', 'U1', 'purchase equipment', '美音 /ˈpɜːrtʃəs/', 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'threat', 'n.', '/θret/', '威胁;坏事发生的可能', 'Giving up too early is the biggest threat to learning.', '过早放弃是学习最大的威胁。', 'Learning for Life', 39, 0, 'senior', 'wordlist', 'elective1', 'U1', 'a real threat', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'volunteer', 'v./n.', '/ˌvɒlənˈtɪə(r)/', '自愿做;志愿者', 'Many students volunteer to teach younger children after class.', '许多学生自愿在课后教年幼的孩子。', 'Learning for Life', 40, 0, 'senior', 'wordlist', 'elective1', 'U1', 'volunteer to help', '美音 /ˌvɑːlənˈtɪr/', 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'occur', 'v.', '/əˈkɜː(r)/', '发生;出现;想到', 'Learning may occur at home, in the laboratory or in nature.', '学习可能发生在家里、实验室或大自然中。', 'Learning for Life', 41, 0, 'senior', 'wordlist', 'elective1', 'U1', 'learning occurs', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'frequently', 'adv.', '/ˈfriːkwəntli/', '频繁地;经常地', 'She was frequently brought forward to recite when visitors came.', '有客人来时她常被叫上前去背诵。', 'Learning for Life', 42, 0, 'senior', 'wordlist', 'elective1', 'U1', 'frequently asked', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'gradually', 'adv.', '/ˈɡrædʒuəli/', '逐渐地;渐渐地', 'Gradually she acquired a strong taste for poetry.', '渐渐地,她对诗歌产生了浓厚的兴趣。', 'Learning for Life', 43, 0, 'senior', 'wordlist', 'elective1', 'U1', 'gradually develop', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'acquire', 'v.', '/əˈkwaɪə(r)/', '获得;习得;学到', 'Through the club I acquired practical knowledge about the environment.', '通过这个社团我获得了关于环境的实用知识。', 'Learning for Life', 44, 0, 'senior', 'wordlist', 'elective1', 'U1', 'acquire knowledge', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'willingly', 'adv.', '/ˈwɪlɪŋli/', '乐意地;自愿地', 'She willingly learned long passages from great poets by heart.', '她乐意地把伟大诗人的长篇段落背了下来。', 'Learning for Life', 45, 0, 'senior', 'wordlist', 'elective1', 'U1', 'learn willingly', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'effective', 'adj.', '/ɪˈfektɪv/', '有效的;起作用的', 'His teacher''s tips turned out to be quite effective.', '他老师的建议结果很有效。', 'Learning for Life', 46, 0, 'senior', 'wordlist', 'elective1', 'U1', 'prove effective', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'responsibility', 'n.', '/rɪˌspɒnsəˈbɪləti/', '责任;职责;责任心', 'Working in the club, my sense of responsibility has grown.', '在社团里工作,我的责任心增强了。', 'Learning for Life', 47, 0, 'senior', 'wordlist', 'elective1', 'U1', 'a sense of responsibility', '美音 /rɪˌspɑːnsəˈbɪləti/', 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'lifelong', 'adj.', '/ˈlaɪflɒŋ/', '终身的;毕生的', 'Lifelong learning means we keep growing all through our lives.', '终身学习意味着我们一生都在不断成长。', 'Learning for Life', 48, 0, 'senior', 'wordlist', 'elective1', 'U1', 'lifelong learning', '美音 /ˈlaɪflɔːŋ/', 'sufe');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('se1u1.01', '①过去完成时(had done:过去的过去)', 'A2', 11, '上外版选择性必修第一册 U1 — 表示在过去某一时间或动作之前已经完成的动作(过去的过去)。常与 before / by the time / when / already / by + 过去时间 连用:When I arrived, the class had begun.', 1, 'elective1', 'U1', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'sufe');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('se1u1.02', '②现在完成进行时(have/has been doing:持续到现在)', 'A2', 11, '上外版选择性必修第一册 U1 — 表示从过去某时开始、一直持续到现在(可能还在继续)的动作,强调动作的持续。常与 for / since / all day / lately / recently / how long 连用:She has been studying for hours.', 2, 'elective1', 'U1', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'sufe');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('se1u1.03', '③将来进行时(will be doing:将来正在进行)', 'A2', 11, '上外版选择性必修第一册 U1 — 表示将来某一时刻或时段正在进行的动作。常与 this time tomorrow / at + 将来时刻 / soon / when you grow up 连用:This time tomorrow I''ll be flying to London.', 3, 'elective1', 'U1', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'sufe');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U1' AND code='se1u1.01'), 'By the time the visitors arrived, Curie ____ the long poem.', 'had already recited', 'recites', 'has recited', 'will recite', 'A', 'by the time + 过去动作之前已完成 → 过去完成时 had recited。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U1' AND code='se1u1.01'), 'When the teacher came in, the experiment ____, so we had to start again.', 'fails', 'had already failed', 'is failing', 'will fail', 'B', '过去某动作(came in)之前已发生 → had failed。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U1' AND code='se1u1.01'), 'Just nine days after he ____ his degree, the physicist sailed home.', 'gains', 'has gained', 'had gained', 'is gaining', 'C', 'after 引导、动作早于过去的 sailed → 过去完成时。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U1' AND code='se1u1.01'), 'Before he taught himself to write, the boy ____ with reading for years.', 'struggles', 'has struggled', 'will struggle', 'had struggled', 'D', 'before 过去动作之前的持续 → 过去完成时 had struggled。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U1' AND code='se1u1.01'), 'She told us that she ____ those poems by heart long before.', 'had learned', 'learns', 'has learned', 'is learning', 'A', '主句过去 told,从句更早 → 过去完成时。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U1' AND code='se1u1.01'), 'By 1937, Deng''s father ____ him a deep love of science.', 'gives', 'had given', 'has given', 'will give', 'B', 'by + 过去年份,之前已完成 → had given。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U1' AND code='se1u1.01'), 'When I got home, my mother ____ the books for my evening study.', 'prepares', 'has prepared', 'had already prepared', 'is preparing', 'C', '过去 got home 之前已完成 → 过去完成时。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U1' AND code='se1u1.01'), 'Mandela realised that the donkey ____ him off before his friends could laugh.', 'throws', 'has thrown', 'will throw', 'had thrown', 'D', '过去 realised 之前发生 → had thrown。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U1' AND code='se1u1.01'), 'After the war ____, Goodenough went to Chicago to study physics.', 'had ended', 'ends', 'has ended', 'is ending', 'A', 'after 过去动作之前完成 → 过去完成时。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U1' AND code='se1u1.01'), 'Darwin found that his brother ____ a small laboratory in the garden.', 'builds', 'had built', 'has built', 'will build', 'B', '过去 found,从句动作更早 → 过去完成时。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U1' AND code='se1u1.01'), 'By the end of that summer, he ____ several books on chemistry.', 'reads', 'has read', 'had read', 'is reading', 'C', 'by the end of + 过去时间 → 过去完成时。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U1' AND code='se1u1.01'), 'She wanted to run away because she ____ never ____ in front of strangers before.', 'does; recite', 'has; recited', 'will; recite', 'had; recited', 'D', '过去 wanted 之前的''从未……过'' → 过去完成时 had recited。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U1' AND code='se1u1.01'), 'The class was over; clearly the bell ____ a few minutes earlier.', 'had rung', 'rings', 'has rung', 'is ringing', 'A', '过去 was over 之前更早发生 → had rung。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U1' AND code='se1u1.01'), 'Until he climbed the hill, he ____ how much farther one could see.', 'does not realise', 'had not realised', 'has not realised', 'will not realise', 'B', 'until + 过去动作之前一直未……→ 过去完成时。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U1' AND code='se1u1.01'), 'He said the wise man ____ himself every day before his conduct grew faultless.', 'examines', 'has examined', 'had examined', 'is examining', 'C', '过去 said,更早的反省 → 过去完成时。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U1' AND code='se1u1.01'), 'By the time she finished school, she ____ a strong taste for poetry.', 'develops', 'has developed', 'will develop', 'had developed', 'D', 'by the time + 过去 → 过去完成时。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U1' AND code='se1u1.01'), 'When the prize was announced, Goodenough ____ already ____ ninety-seven.', 'had; turned', 'does; turn', 'has; turned', 'will; turn', 'A', '过去 announced 之前已发生 → 过去完成时。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U1' AND code='se1u1.01'), 'He admitted that he ____ that lesson from the donkey years before.', 'learns', 'had learned', 'has learned', 'is learning', 'B', '过去 admitted,更早的 learned → 过去完成时。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U1' AND code='se1u1.01'), 'Before the steamship reached China, the young man ____ how to serve his country.', 'decides', 'has decided', 'had decided', 'will decide', 'C', 'before 过去动作之前 → 过去完成时。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U1' AND code='se1u1.01'), 'No sooner ____ he ____ his Ph.D. than he joined a research lab.', 'does; earn', 'has; earned', 'will; earn', 'had; earned', 'D', 'no sooner ... than 句型用过去完成时。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U1' AND code='se1u1.02'), 'Our motherland ____ from the attack for so long, the father said sadly.', 'has been suffering', 'suffered', 'had suffered', 'will suffer', 'A', 'for so long、持续到现在并强调持续 → 现在完成进行时。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U1' AND code='se1u1.02'), 'I ____ on my English recently, so I feel much more confident now.', 'worked', 'have been working', 'had worked', 'will work', 'B', 'recently + 持续到现在 → 现在完成进行时。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U1' AND code='se1u1.02'), 'He ____ in the Go Green Club since last October.', 'worked', 'had worked', 'has been working', 'is working', 'C', 'since + 过去时间点、持续至今 → 现在完成进行时。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U1' AND code='se1u1.02'), 'She ____ long poems by heart all afternoon and is still going.', 'learned', 'had learned', 'will learn', 'has been learning', 'D', 'all afternoon + 仍在继续 → 现在完成进行时。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U1' AND code='se1u1.02'), 'I ____ to English radio every day for months to get used to the speed.', 'have been listening', 'listened', 'had listened', 'will listen', 'A', 'for months + 持续动作 → 现在完成进行时。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U1' AND code='se1u1.02'), 'How long ____ you ____ reading exercises under your teacher''s guidance?', 'did; do', 'have; been doing', 'had; done', 'will; do', 'B', 'how long + 持续到现在 → 现在完成进行时。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U1' AND code='se1u1.02'), 'Goodenough ____ new types of batteries since he was a young man.', 'researched', 'had researched', 'has been researching', 'will research', 'C', 'since + 从句、持续至今 → 现在完成进行时。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U1' AND code='se1u1.02'), 'I ____ from you lately—how has your study been going?', 'did not hear', 'had not heard', 'will not hear', 'have not been hearing', 'D', 'lately + 强调一段时间 → 现在完成进行时。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U1' AND code='se1u1.02'), 'My sense of responsibility ____ steadily ever since I joined the club.', 'has been growing', 'grew', 'had grown', 'will grow', 'A', 'ever since + 持续发展 → 现在完成进行时。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U1' AND code='se1u1.02'), 'They ____ wild honey in the fields all day, and their baskets are nearly full.', 'gathered', 'have been gathering', 'had gathered', 'will gather', 'B', 'all day + 仍在进行 → 现在完成进行时。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U1' AND code='se1u1.02'), 'He ____ at chemistry hard for weeks, so his hands are stained with dye.', 'worked', 'had worked', 'has been working', 'will work', 'C', 'for weeks + 现在仍有结果 → 现在完成进行时。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U1' AND code='se1u1.02'), 'We ____ on this design project since early spring without a break.', 'worked', 'had worked', 'will work', 'have been working', 'D', 'since early spring + 持续 → 现在完成进行时。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U1' AND code='se1u1.02'), 'Why are your eyes so red? — I ____ for the test since this morning.', 'have been studying', 'studied', 'had studied', 'will study', 'A', 'since this morning + 持续到现在(眼睛红) → 现在完成进行时。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U1' AND code='se1u1.02'), 'The old pianist ____ with his teacher for years and still practises weekly.', 'practised', 'has been practising', 'had practised', 'will practise', 'B', 'for years + 仍在继续 → 现在完成进行时。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U1' AND code='se1u1.02'), 'I ____ a lot of reading exercises lately, and my marks are improving.', 'did', 'had done', 'have been doing', 'will do', 'C', 'lately + 持续到现在并有结果 → 现在完成进行时。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U1' AND code='se1u1.02'), 'She ____ about lifelong learning ever since she read that book.', 'thought', 'had thought', 'will think', 'has been thinking', 'D', 'ever since + 持续 → 现在完成进行时。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U1' AND code='se1u1.02'), 'They ____ to reduce food waste in the canteen for the whole term.', 'have been trying', 'tried', 'had tried', 'will try', 'A', 'for the whole term + 持续至今 → 现在完成进行时。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U1' AND code='se1u1.02'), 'How long ____ he ____ in this laboratory? — Since he was thirty.', 'did; research', 'has; been researching', 'had; researched', 'will; research', 'B', 'how long ... since → 现在完成进行时。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U1' AND code='se1u1.02'), 'I ____ my own voice and comparing it with the host''s for a month now.', 'recorded', 'had recorded', 'have been recording', 'will record', 'C', 'for a month now + 持续 → 现在完成进行时。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U1' AND code='se1u1.02'), 'My twin sister ____ for the chemistry exam since breakfast, and looks tired.', 'prepared', 'had prepared', 'will prepare', 'has been preparing', 'D', 'since breakfast + 持续到现在 → 现在完成进行时。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U1' AND code='se1u1.03'), 'I ____ for my country soon, the young scientist said on the ship.', 'will be working', 'worked', 'have worked', 'had worked', 'A', 'soon + 将来正在进行 → 将来进行时。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U1' AND code='se1u1.03'), 'For the country''s future, you ____ science when you grow up.', 'studied', 'will be studying', 'have studied', 'had studied', 'B', 'when you grow up + 将来正在进行 → 将来进行时。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U1' AND code='se1u1.03'), 'This time next week she ____ an important English test.', 'takes', 'has taken', 'will be taking', 'took', 'C', 'this time next week + 将来某刻在进行 → 将来进行时。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U1' AND code='se1u1.03'), 'Next Friday we ____ kindergarten kids how to reuse glass bottles.', 'showed', 'have shown', 'had shown', 'will be showing', 'D', 'next Friday + 将来某时进行 → 将来进行时。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U1' AND code='se1u1.03'), 'This time tomorrow my sister ____ an experiment in the lab.', 'will be doing', 'does', 'has done', 'did', 'A', 'this time tomorrow + 将来正在进行 → 将来进行时。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U1' AND code='se1u1.03'), 'Don''t call me at nine; I ____ a long passage for the speech contest.', 'recite', 'will be reciting', 'have recited', 'recited', 'B', 'at nine(将来时刻)+ 在进行 → 将来进行时。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U1' AND code='se1u1.03'), 'At this moment next month, he ____ batteries in his Oxford laboratory.', 'researches', 'has researched', 'will be researching', 'researched', 'C', 'at this moment next month + 将来在进行 → 将来进行时。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U1' AND code='se1u1.03'), 'By eight tomorrow evening, the students ____ for their group project.', 'work', 'have worked', 'worked', 'will be working', 'D', 'by eight tomorrow evening(将来时段)+ 在进行 → 将来进行时。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U1' AND code='se1u1.03'), 'When you arrive at the club, we ____ ways to reduce food waste.', 'will be discussing', 'discuss', 'have discussed', 'discussed', 'A', '将来 when 时间状语 + 在进行 → 将来进行时。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U1' AND code='se1u1.03'), 'This time tomorrow afternoon, Jack ____ the piano with his teacher.', 'practises', 'will be practising', 'has practised', 'practised', 'B', 'this time tomorrow afternoon + 在进行 → 将来进行时。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U1' AND code='se1u1.03'), 'Don''t worry—at ten o''clock the host ____ the same programme as usual.', 'broadcasts', 'has broadcast', 'will be broadcasting', 'broadcast', 'C', 'at ten o''clock(将来)+ 例行进行 → 将来进行时。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U1' AND code='se1u1.03'), 'This weekend the volunteers ____ younger children with their reading.', 'help', 'have helped', 'helped', 'will be helping', 'D', 'this weekend + 将来在进行 → 将来进行时。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U1' AND code='se1u1.03'), 'By next term, I hope I ____ my own voice every day to improve.', 'will be recording', 'record', 'have recorded', 'recorded', 'A', 'by next term + 将来在进行 → 将来进行时。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U1' AND code='se1u1.03'), 'At noon tomorrow the team ____ their plan for the learning festival.', 'presents', 'will be presenting', 'has presented', 'presented', 'B', 'at noon tomorrow + 在进行 → 将来进行时。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U1' AND code='se1u1.03'), 'This time next year, many of us ____ at different universities.', 'study', 'have studied', 'will be studying', 'studied', 'C', 'this time next year + 将来某刻在进行 → 将来进行时。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U1' AND code='se1u1.03'), 'When you call me tonight, I ____ for the listening test.', 'prepare', 'have prepared', 'prepared', 'will be preparing', 'D', '将来 tonight + when 时间状语,在进行 → 将来进行时。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U1' AND code='se1u1.03'), 'At this time on Saturday, the children ____ lanterns and paper cranes.', 'will be making', 'make', 'have made', 'made', 'A', 'at this time on Saturday + 在进行 → 将来进行时。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U1' AND code='se1u1.03'), 'Soon he ____ his birthday party, so he is busy preparing now.', 'celebrates', 'will be celebrating', 'has celebrated', 'celebrated', 'B', 'soon + 将来在进行 → 将来进行时。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U1' AND code='se1u1.03'), 'This time tomorrow, the interviewer ____ students about learning by doing.', 'asks', 'has asked', 'will be asking', 'asked', 'C', 'this time tomorrow + 在进行 → 将来进行时。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U1' AND code='se1u1.03'), 'At three o''clock next Monday, we ____ to old people at the nursing home.', 'read', 'have read', 'read aloud', 'will be reading', 'D', 'at three o''clock next Monday + 将来在进行 → 将来进行时。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'Curie''s First Teacher', 'Marie Curie started school when she was only six years old. Because she was the youngest and smallest in her class, she was frequently brought forward to recite in front of visitors. This was a great trial for the shy girl, and she often wanted to run away and hide. Luckily, her father was an excellent educator who knew how to help. He was familiar with both Polish and foreign poetry, and he even wrote little poems himself. On Saturday evenings, he used to recite or read masterpieces of poetry to the whole family. These quiet evenings were a great pleasure for the children. Under his patient guidance, Curie gradually acquired a strong taste for poetry. In the end, she willingly learned long passages by heart and recited them to others. The girl who once wanted to hide had become a confident learner, all because of her father''s gentle, lifelong love of books.', '记叙·居里的诗歌启蒙', 153, '[{"q":"Why did young Curie often want to run away?","answer":"A","options":["Reciting before visitors frightened the shy girl.","She disliked her father''s poems.","Her class was too large to enjoy.","She had to look after her brothers."],"explanation":"原文 ''a great trial for the shy girl, and she often wanted to run away'' 的转述。"},{"q":"How did her father help her learn?","answer":"B","options":["By making her recite alone every night.","By sharing his love of poetry with the family.","By sending her to a famous school.","By punishing her when she was shy."],"explanation":"原文 ''used to recite or read masterpieces of poetry to the whole family'' 的概括。"},{"q":"What change happened to Curie in the end?","answer":"A","options":["She turned into a confident learner.","She gave up reading poems for good.","She forgot the passages she had learned.","She started to dislike her father."],"explanation":"末段 ''had become a confident learner'' 的转述;其余与原文相反。"}]'::jsonb, '[{"word":"recite","cn":"背诵"},{"word":"trial","cn":"考验"},{"word":"educator","cn":"教育家"},{"word":"guidance","cn":"指导"}]'::jsonb, 2, 'elective1', 'U1', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'Lessons in the Garden', 'Towards the end of his school days, Charles Darwin found a new kind of learning far from any classroom. His brother worked hard at chemistry and made a small laboratory in the tool-house in the garden. Darwin was allowed to help him with most of his experiments. Together they made many gases and compounds, and Darwin also read several books on chemistry with great care. The subject interested him so much that the two brothers often kept working till late at night. Looking back, Darwin felt that this was the best part of his whole education, for it showed him practically the meaning of experimental science. Somehow the news that they were studying chemistry got known at school, and his classmates nicknamed him ''Gas''. Yet the teasing did not trouble him at all. He had discovered that real learning could happen anywhere, and that a simple garden shed could teach more than many ordinary lessons.', '记叙·达尔文的实验室启蒙', 155, '[{"q":"Where did Darwin do his chemistry learning?","answer":"B","options":["In the main school laboratory.","In a small lab his brother built in the garden.","In a famous university classroom.","At a friend''s house in town."],"explanation":"原文 ''made a small laboratory in the tool-house in the garden'' 的转述。"},{"q":"How did Darwin feel about this part of his education?","answer":"C","options":["He thought it was a waste of his time.","He was ashamed of the nickname.","He saw it as the finest part of all his schooling.","He found chemistry boring."],"explanation":"原文 ''the best part of his whole education'' 的转述。"},{"q":"What main idea does Darwin''s story show?","answer":"D","options":["Only schools can offer real learning.","Teasing always stops people from learning.","Chemistry is harder than other subjects.","Real learning can take place anywhere."],"explanation":"末段 ''real learning could happen anywhere'' 的概括。"}]'::jsonb, '[{"word":"laboratory","cn":"实验室"},{"word":"experiment","cn":"实验"},{"word":"practically","cn":"切实地"},{"word":"somehow","cn":"不知怎么地"}]'::jsonb, 2, 'elective1', 'U1', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'A Lesson from a Donkey', 'When Nelson Mandela was no more than five, he became a herd-boy, looking after sheep in the fields. It was there, far from any school, that he learned countless skills: how to gather wild honey, how to swim in cold streams, and how to catch fish. But his deepest lesson came from an unruly donkey. One day he and his friends were taking turns riding it. When Mandela''s turn came, the donkey suddenly rushed into a bush, bent its head, and threw him off, which embarrassed him in front of everyone. He had lost face among his friends. Yet the young boy did not simply feel angry. He understood that to shame another person is to make him suffer an unnecessarily cruel fate. From that small accident he drew a great rule for life: even when you win, you should never dishonour those you defeat. As a boy he had already begun to learn the meaning of true dignity.', '记叙·曼德拉的田野课', 159, '[{"q":"What did Mandela learn in the fields?","answer":"A","options":["Many practical outdoor skills.","How to read foreign books.","How to write English poems.","How to do science experiments."],"explanation":"原文列举 gather honey / swim / catch fish 等户外技能的概括。"},{"q":"What did the donkey accident teach him?","answer":"B","options":["That riding animals is dangerous.","That shaming others causes needless suffering.","That he should never play with friends.","That losing face does not matter at all."],"explanation":"原文 ''to shame another person is to make him suffer an unnecessarily cruel fate'' 的转述。"},{"q":"How did he later treat people he beat?","answer":"C","options":["He shamed them in front of their friends.","He refused to compete with them.","He won without taking away their dignity.","He avoided them completely."],"explanation":"末段 ''never dignity... never dishonour those you defeat'' 的转述。"}]'::jsonb, '[{"word":"gather","cn":"采集"},{"word":"embarrass","cn":"使尴尬"},{"word":"dignity","cn":"尊严"},{"word":"defeat","cn":"战胜"}]'::jsonb, 2, 'elective1', 'U1', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'Never Too Old to Learn', 'John Goodenough is proof that learning has no age limit. As a child, he struggled with reading because of a learning disorder, yet he taught himself to write and won a place at a boarding school. The strict education there prepared him well, and he later graduated with honours in mathematics. After the Second World War he went to study physics, a completely new subject for him, and earned a Ph.D. in 1952. Years later, while working at Oxford, he researched the properties of materials in order to produce better rechargeable batteries. His pioneering work made a major breakthrough possible, leading to safer batteries for phones and electric cars. In 2019 he received the Nobel Prize in Chemistry at the age of ninety-seven. Many people had told him he was too old to succeed, but he had not taken it to heart. Even now he goes to his laboratory every day, saying, ''I''m only 97. I still have time to go.''', '记叙·古德纳夫的晚成', 161, '[{"q":"What problem did Goodenough face as a child?","answer":"D","options":["He had no school to attend.","He hated mathematics.","He was too poor to study.","He had great trouble with reading."],"explanation":"原文 ''struggled with reading because of a learning disorder'' 的转述。"},{"q":"What did his research at Oxford help to create?","answer":"A","options":["Better and safer rechargeable batteries.","A new kind of school.","A famous chemistry prize.","A faster steamship."],"explanation":"原文 ''better rechargeable batteries... safer batteries for phones and electric cars'' 的转述。"},{"q":"What does his story mainly teach us?","answer":"B","options":["Only young people can win prizes.","It is never too late to keep learning.","Science is too hard for most people.","Old age always brings failure."],"explanation":"标题与全文 ''learning has no age limit / still have time to go'' 的概括。"}]'::jsonb, '[{"word":"struggle","cn":"艰难地做"},{"word":"scholarship","cn":"奖学金"},{"word":"breakthrough","cn":"突破"},{"word":"honour","cn":"荣誉"}]'::jsonb, 2, 'elective1', 'U1', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'Xunzi on Learning', 'More than two thousand years ago, the Chinese thinker Xunzi wrote that learning should never cease. He used simple pictures to make his point. Blue dye comes from the indigo plant, he said, yet it is bluer than the plant itself; this shows how a learner can go beyond the teacher. If wood is pressed against a board, it can be made straight; if metal is put to the grindstone, it can be sharpened. In the same way, a person who studies widely and examines himself each day will see his wisdom grow clear and his conduct become faultless. Xunzi also reminded people to be patient. Unless you pile up tiny streams, you can never make a river; unless you take little steps, you can never travel a thousand li. Even the finest horse cannot cross the land in one leap. True achievement, he taught, consists in never giving up. If you carve without stopping, you can cut through metal or stone.', '议论·荀子《劝学》', 162, '[{"q":"What does the indigo example show, according to Xunzi?","answer":"C","options":["Blue is the most useful colour.","Plants are stronger than dye.","A learner can surpass the teacher.","Learning is mostly about colours."],"explanation":"原文 ''bluer than the plant... a learner can go beyond the teacher'' 的转述。"},{"q":"Why does Xunzi mention tiny streams and little steps?","answer":"D","options":["To describe the beauty of rivers.","To warn against travelling far.","To explain how horses run.","To stress that progress needs patience."],"explanation":"原文以 streams/steps 强调积累与耐心的概括。"},{"q":"What does Xunzi say true achievement depends on?","answer":"A","options":["Refusing ever to give up.","Being born with great talent.","Studying for only one day.","Carving on soft wood only."],"explanation":"原文 ''achievement... consists in never giving up'' 的转述。"}]'::jsonb, '[{"word":"cease","cn":"停止"},{"word":"press","cn":"压"},{"word":"wisdom","cn":"智慧"},{"word":"carve","cn":"雕刻"}]'::jsonb, 2, 'elective1', 'U1', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'Learning by Doing', 'The idea of learning by doing has become more and more popular among high school students. It proved very effective in one of the most unforgettable courses I ever took in our school Art Club. To my surprise, the course on three-dimensional design was not based on computers at all; instead, it focused on real materials and their properties. In one task, we had to see what structures we could create simply by folding pieces of paper. We were encouraged to use our hands and cool tools to make as many things as possible, such as paper cranes, lanterns and frogs. In another task, we tried to see how many parts could be removed from a wooden structure before it fell down. The course gave us useful exposure to design principles because it actively engaged us in the learning process. Since then I have been a firm believer that we often understand an idea best only after we have tried it with our own hands.', '议论·学以致用与社团学习', 165, '[{"q":"What surprised the writer about the design course?","answer":"B","options":["It had no teacher at all.","It used no computers and focused on real materials.","It was only about paper cranes.","It was held outside the school."],"explanation":"原文 ''not based on computers at all... focused on real materials'' 的转述。"},{"q":"What did students do in the folding task?","answer":"C","options":["They drew designs on a computer.","They removed wood from a structure.","They made many objects by hand with paper.","They read books on design."],"explanation":"原文 ''use our hands... make as many things as possible'' 的转述。"},{"q":"What does the writer finally believe?","answer":"D","options":["Design can only be learned from books.","Computers teach better than hands do.","Art clubs waste students'' time.","We understand ideas best after trying them ourselves."],"explanation":"末句 ''understand an idea best only after we have tried it'' 的转述。"}]'::jsonb, '[{"word":"effective","cn":"有效的"},{"word":"process","cn":"过程"},{"word":"acquire","cn":"习得"},{"word":"lifelong","cn":"终身的"}]'::jsonb, 2, 'elective1', 'U1', 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective1', 'U1', 'Advice on Improving English', 'Learning English well takes time and the right (1)____. My biggest problem used to be listening: when native speakers talked fast, I could (2)____ only a few words. A classmate gave me some useful (3)____. She told me to listen to English radio every day so that I could get (4)____ to the speed. I also began to (5)____ my own voice and compare it with the host''s, which helped me hear my own (6)____. Little by little, my listening (7)____, and I felt much more (8)____ when foreigners spoke to me. The most important thing, I learned, is never to (9)____ up. If you keep practising, your skills will surely (10)____. Learning a language is a long road, but every small step counts.', 124, 2, '[{"q":"1","answer":"A","options":["method","weather","price","noise"],"explanation":"the right method 正确的方法。"},{"q":"2","answer":"B","options":["sell","catch","throw","hide"],"explanation":"catch only a few words 只能听懂几个词。"},{"q":"3","answer":"C","options":["money","food","advice","games"],"explanation":"useful advice 有用的建议。"},{"q":"4","answer":"D","options":["lost","afraid","tired","used"],"explanation":"get used to 习惯于。"},{"q":"5","answer":"A","options":["record","lose","eat","sell"],"explanation":"record my own voice 录下声音。"},{"q":"6","answer":"B","options":["songs","mistakes","prices","gardens"],"explanation":"hear my own mistakes 听出错误。"},{"q":"7","answer":"C","options":["stopped","failed","improved","disappeared"],"explanation":"my listening improved 听力提高了。"},{"q":"8","answer":"D","options":["afraid","sorry","bored","confident"],"explanation":"more confident 更自信。"},{"q":"9","answer":"A","options":["give","stand","look","wake"],"explanation":"give up 放弃。"},{"q":"10","answer":"B","options":["fall","improve","break","stop"],"explanation":"skills will improve 技能会提高。"}]'::jsonb, 1, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective1', 'U1', 'Thirty Days of a New Habit', 'A speaker once shared a simple idea: try something (1)____ for thirty days. He explained that a month is just long (2)____ to add a good habit or drop a bad one. During his own thirty-day (3)____, he hiked up a mountain and even started to (4)____ a short book. The experience made him feel more confident and (5)____. He gave one piece of (6)____: keep your goals small and (7)____, so that you can really stick to them. A big dream is wonderful, but it is the small daily (8)____ that finally bring change. By the (9)____ of a month, you may be surprised at how much you have (10)____. The secret of lifelong learning, he said, is simply to begin and to keep going.', 126, 2, '[{"q":"1","answer":"C","options":["old","broken","new","empty"],"explanation":"something new 新事物。"},{"q":"2","answer":"D","options":["short","wide","deep","enough"],"explanation":"long enough to 足够长以至于。"},{"q":"3","answer":"A","options":["challenge","price","noise","garden"],"explanation":"thirty-day challenge 三十天挑战。"},{"q":"4","answer":"B","options":["sell","write","throw","lose"],"explanation":"write a short book 写一本短书。"},{"q":"5","answer":"C","options":["lazy","sleepy","adventurous","afraid"],"explanation":"confident and adventurous 自信又爱冒险。"},{"q":"6","answer":"D","options":["money","food","music","advice"],"explanation":"a piece of advice 一条建议。"},{"q":"7","answer":"A","options":["sustainable","wrong","loud","rotten"],"explanation":"small and sustainable 小而可持续。"},{"q":"8","answer":"B","options":["noises","steps","prices","rooms"],"explanation":"small daily steps 每天的小步。"},{"q":"9","answer":"C","options":["price","noise","end","garden"],"explanation":"by the end of a month 一个月结束时。"},{"q":"10","answer":"D","options":["lost","broken","sold","achieved"],"explanation":"how much you have achieved 取得了多少。"}]'::jsonb, 2, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective1', 'U1', 'An Interview about Learning', 'Our school newspaper is holding an (1)____ about what students learn outside the classroom. One girl said the Go Green Club had (2)____ her most of all. She has been a (3)____ there for over a year, taking part in many activities that raise (4)____ of environmental protection. Through this work, she has (5)____ practical knowledge about how to protect nature. Her sense of (6)____ and her team spirit have also grown. ''Learning,'' she said, ''is never (7)____ to classrooms. It can happen anywhere, as long as you are (8)____ to try.'' She added that working with others had taught her how to (9)____ as a team. By the end of the interview, everyone agreed that out-of-class activities can be just as (10)____ as ordinary lessons.', 126, 2, '[{"q":"1","answer":"A","options":["interview","garden","price","machine"],"explanation":"an interview 一次采访。"},{"q":"2","answer":"B","options":["sold","influenced","lost","broken"],"explanation":"influenced her most 对她影响最大。"},{"q":"3","answer":"C","options":["price","noise","member","garden"],"explanation":"a member 一名成员。"},{"q":"4","answer":"D","options":["prices","noises","songs","awareness"],"explanation":"raise awareness 提高意识。"},{"q":"5","answer":"A","options":["acquired","lost","sold","broken"],"explanation":"acquired practical knowledge 获得实用知识。"},{"q":"6","answer":"B","options":["price","responsibility","noise","weather"],"explanation":"sense of responsibility 责任感。"},{"q":"7","answer":"C","options":["open","free","limited","ready"],"explanation":"never limited to 从不局限于。"},{"q":"8","answer":"D","options":["afraid","sorry","tired","willing"],"explanation":"willing to try 愿意尝试。"},{"q":"9","answer":"A","options":["cooperate","sleep","shout","hide"],"explanation":"cooperate as a team 团队合作。"},{"q":"10","answer":"B","options":["useless","valuable","boring","empty"],"explanation":"just as valuable 同样有价值。"}]'::jsonb, 3, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective1', 'U1', 'The Ninety-Year-Old Piano Man', 'Jack is a remarkable old man who is still (1)____ to learn. He joined the army many years ago, but only late in life did he begin to (2)____ the piano. Now, at over ninety, he still (3)____ with his teacher for forty-five minutes every two weeks. His birthday is coming, and he is busy (4)____ for his party. People who meet him are always (5)____ by his energy. ''Age is just a (6)____,'' he likes to say. ''You are never too old to (7)____ something new.'' His teacher describes him as a hard-working and (8)____ student who never misses a lesson. Jack believes that music keeps his mind (9)____ and his heart young. His story reminds us that lifelong learning can bring great (10)____ at any age.', 128, 2, '[{"q":"1","answer":"C","options":["afraid","sorry","eager","tired"],"explanation":"eager to learn 渴望学习。"},{"q":"2","answer":"D","options":["sell","throw","lose","play"],"explanation":"play the piano 弹钢琴。"},{"q":"3","answer":"A","options":["practises","sleeps","shouts","hides"],"explanation":"practises with his teacher 和老师练习。"},{"q":"4","answer":"B","options":["selling","preparing","losing","breaking"],"explanation":"preparing for his party 为聚会做准备。"},{"q":"5","answer":"C","options":["bored","angry","amazed","afraid"],"explanation":"amazed by his energy 被他的活力震撼。"},{"q":"6","answer":"D","options":["price","noise","garden","number"],"explanation":"age is just a number 年龄只是个数字。"},{"q":"7","answer":"A","options":["learn","forget","lose","sell"],"explanation":"learn something new 学新东西。"},{"q":"8","answer":"B","options":["lazy","patient","rude","sleepy"],"explanation":"hard-working and patient 勤奋而有耐心。"},{"q":"9","answer":"C","options":["empty","broken","active","silent"],"explanation":"keeps his mind active 让头脑活跃。"},{"q":"10","answer":"D","options":["trouble","noise","danger","joy"],"explanation":"bring great joy 带来巨大的快乐。"}]'::jsonb, 4, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective1', 'U1', 'The Power of Reading', 'When I was young, books opened a door to a wider (1)____. My grandfather, who was a quiet (2)____, kept a shelf full of stories and poems. Every evening he would (3)____ a few pages aloud to me. At first I did not understand much, but I (4)____ began to fall in love with words. Reading taught me that real (5)____ is to know how little we actually know. It also gave me the (6)____ to ask questions and to think for myself. Whenever I felt sad, a good book could (7)____ me and lift my mood. Books, I learned, are patient teachers that never (8)____ giving us their wisdom. They connect us with people who lived (9)____ years ago. Now I believe that anyone who keeps reading will keep (10)____ for a whole lifetime.', 135, 2, '[{"q":"1","answer":"A","options":["world","price","noise","machine"],"explanation":"a wider world 更广阔的世界。"},{"q":"2","answer":"B","options":["price","educator","noise","garden"],"explanation":"a quiet educator 一位安静的教育者。"},{"q":"3","answer":"C","options":["sell","throw","recite","lose"],"explanation":"recite a few pages aloud 朗读几页。"},{"q":"4","answer":"D","options":["never","rarely","seldom","gradually"],"explanation":"gradually began to 渐渐开始。"},{"q":"5","answer":"A","options":["knowledge","weather","price","noise"],"explanation":"real knowledge 真正的知识。"},{"q":"6","answer":"B","options":["price","courage","noise","garden"],"explanation":"the courage to ask 提问的勇气。"},{"q":"7","answer":"C","options":["hurt","lose","comfort","sell"],"explanation":"comfort me 安慰我。"},{"q":"8","answer":"D","options":["start","enjoy","love","stop"],"explanation":"never stop giving 从不停止给予。"},{"q":"9","answer":"A","options":["thousands of","few","no","single"],"explanation":"thousands of years ago 数千年前。"},{"q":"10","answer":"B","options":["falling","growing","stopping","failing"],"explanation":"keep growing 不断成长。"}]'::jsonb, 5, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective1', 'U1', 'What I Learned by Doing', 'Last term I joined a design course that completely changed the way I (1)____. Instead of sitting and listening, we learned by (2)____ things with our own hands. Our teacher gave each of us some paper and (3)____ us to build the tallest tower we could. At first my tower kept (4)____ down, and I almost wanted to give up. But I was (5)____ to keep trying, and slowly I found a better (6)____. When my tower finally stood tall, I felt a deep sense of (7)____. The course showed me, in a very (8)____ way, that mistakes are part of learning. Every time something fell, I (9)____ a little more about balance and weight. Now I am a firm believer that we understand an idea best after we have (10)____ it ourselves.', 133, 2, '[{"q":"1","answer":"C","options":["sell","throw","learn","hide"],"explanation":"the way I learn 我学习的方式。"},{"q":"2","answer":"D","options":["losing","selling","breaking","making"],"explanation":"learning by making things 通过动手做来学。"},{"q":"3","answer":"A","options":["encouraged","sold","lost","forgot"],"explanation":"encouraged us to build 鼓励我们搭建。"},{"q":"4","answer":"B","options":["growing","falling","rising","standing"],"explanation":"kept falling down 一直倒下。"},{"q":"5","answer":"C","options":["afraid","sorry","determined","lazy"],"explanation":"determined to keep trying 决心继续尝试。"},{"q":"6","answer":"D","options":["noise","price","garden","method"],"explanation":"a better method 更好的方法。"},{"q":"7","answer":"A","options":["achievement","fear","anger","sadness"],"explanation":"a sense of achievement 成就感。"},{"q":"8","answer":"B","options":["wrong","practical","empty","boring"],"explanation":"in a very practical way 以非常实际的方式。"},{"q":"9","answer":"C","options":["forgot","lost","learned","sold"],"explanation":"learned a little more 学到更多。"},{"q":"10","answer":"D","options":["lost","sold","broken","tried"],"explanation":"after we have tried it 在亲手试过之后。"}]'::jsonb, 6, 'sufe');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U1 听力·对话 Choosing a School Club', '上外版选择性必修第一册 U1 · dialogue', 3, 'Tina: Which school club are you going to join this term, Sam?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U1 听力·短文 Learning Is Everywhere', '上外版选择性必修第一册 U1 · passage', 2, 'Learning is never limited to classrooms. It may happen at home, in a laboratory, or out in nature. Marie Curie learned a love of poetry from her father at home. Charles Darwin discovered the joy of science in a simple garden shed. Nelson Mandela learned important lessons while looking after sheep in the fields. Their stories remind us that real learning can take place anywhere, at any age.', '学习从不局限于教室。它可能发生在家里、实验室或大自然中。居里在家从父亲那里学会了热爱诗歌;达尔文在简陋的花园棚里发现了科学的乐趣;曼德拉在田野放羊时学到重要的人生课。他们的故事提醒我们,真正的学习可以发生在任何地方、任何年龄。', 'uk_female', '[{"q":"What is the main message of the passage?","type":"choice","answer":"D","options":["Only schools can teach us.","Poetry is the best subject.","Learning is limited to books.","Learning can happen anywhere."]},{"q":"Where did Curie learn to love poetry?","type":"choice","answer":"A","options":["At home from her father.","In a large school.","In a laboratory.","In the fields."]},{"q":"Where did Darwin find the joy of science?","type":"choice","answer":"B","options":["In a famous university.","In a simple garden shed.","On a steamship.","In a music club."]},{"q":"What was Mandela doing when he learned his lessons?","type":"choice","answer":"C","options":["Reading poems.","Doing experiments.","Looking after sheep.","Playing the piano."]},{"q":"What do the three stories remind us?","type":"choice","answer":"D","options":["Science is too hard.","Only children can learn.","Poetry is useless.","Real learning can happen anywhere and at any age."]}]'::jsonb, '[]'::jsonb, 'short', 'elective1', 'U1', 'sufe');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U1 听力·对话 Planning to Study Abroad', '上外版选择性必修第一册 U1 · dialogue', 3, 'Wu Xuan: I''ve been working on my English a lot recently.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U1 听力·短文 Try Something New for 30 Days', '上外版选择性必修第一册 U1 · passage', 2, 'Here is a simple idea for lifelong learners: try something new for thirty days. A month is just long enough to build a good habit or break a bad one. One man used this idea to hike up a high mountain and even to write a short book. He became more confident and adventurous. His advice is to keep your goals small and easy to keep, because small daily steps are what finally bring real change.', '给终身学习者一个简单的点子:坚持尝试新事物三十天。一个月刚好够养成一个好习惯或改掉一个坏习惯。有个人用这个方法登上高山,甚至写了一本短书。他变得更自信、更爱冒险。他的建议是把目标定得小而易于坚持,因为正是每天的小步带来真正的改变。', 'uk_female', '[{"q":"What is the simple idea in the passage?","type":"choice","answer":"B","options":["Sleep for thirty days.","Try something new for thirty days.","Travel for a whole year.","Read only one book."]},{"q":"Why is a month long enough?","type":"choice","answer":"C","options":["It is the longest time possible.","It costs no money.","It can help build a habit or break one.","It never feels boring."]},{"q":"What did one man do with this idea?","type":"choice","answer":"D","options":["He stopped all learning.","He slept every afternoon.","He gave up his job.","He hiked a mountain and wrote a short book."]},{"q":"How did the man change?","type":"choice","answer":"A","options":["He became more confident and adventurous.","He became lazy and tired.","He grew afraid of new things.","He lost all his confidence."]},{"q":"What is the man''s advice?","type":"choice","answer":"B","options":["Set the biggest goals you can.","Keep goals small and easy to keep.","Never make any plans.","Change your goal every day."]}]'::jsonb, '[]'::jsonb, 'short', 'elective1', 'U1', 'sufe');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U1 听力·对话 Advice on Time Management', '上外版选择性必修第一册 U1 · dialogue', 3, 'Ben: I never seem to have enough time for my studies. Any advice?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U1 听力·短文 The Value of Learning by Doing', '上外版选择性必修第一册 U1 · passage', 2, 'Many great thinkers believed that we learn best by doing. Xunzi, an ancient Chinese teacher, said that learning should never stop and that true success comes from never giving up. Modern teachers agree. When students fold paper, build towers or grow plants, they remember far more than from books alone. Each small mistake teaches them something new. So the next time you face a hard task, do not just read about it. Try it with your own hands, and learn.', '许多伟大的思想家都相信我们在动手中学得最好。古代中国老师荀子说,学习不应停止,真正的成功来自永不放弃。现代教师也认同。当学生折纸、搭塔或种植物时,他们记住的远比只看书多。每一个小错误都教会他们新东西。所以下次面对难题时,别只是读它,用你自己的双手去尝试、去学习。', 'uk_female', '[{"q":"What did many great thinkers believe?","type":"choice","answer":"D","options":["Books are the only teachers.","Learning should stop early.","Mistakes are useless.","We learn best by doing."]},{"q":"What did Xunzi say about learning?","type":"choice","answer":"A","options":["It should never stop.","It is only for the young.","It needs no effort.","It is a waste of time."]},{"q":"What helps students remember more?","type":"choice","answer":"B","options":["Reading books alone.","Doing things with their hands.","Sleeping in class.","Copying answers."]},{"q":"What does each small mistake do?","type":"choice","answer":"C","options":["It stops all learning.","It makes students give up.","It teaches them something new.","It wastes their time."]},{"q":"What does the speaker suggest doing with a hard task?","type":"choice","answer":"D","options":["Only read about it.","Avoid it completely.","Ask someone else to do it.","Try it with your own hands."]}]'::jsonb, '[]'::jsonb, 'short', 'elective1', 'U1', 'sufe');
INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit, publisher) VALUES (11, 'Write a Website Article about "Learning by Doing"(写一篇关于"做中学"的网站短文)', 'The Art of Learning by Doing', '假设你叫李军,你为学校学生会的"做中学(Learning by Doing)"活动征稿。请用英语写一篇约100词的网站短文,内容包括:① 提出一个关于"做中学"的总观点;② 用你自己(或他人)的一段亲身经历作为支撑细节;③ 用一句话总结。注意:用上本单元时态(过去完成时/现在完成进行时/将来进行时),用个人经历让观点更有说服力。', 'Suppose you are Li Jun. You are calling for articles for your school''s "Learning by Doing" event. Write a short website article (about 100 words) that: 1) gives a general statement about learning by doing; 2) uses your own (or someone else''s) personal experience as supporting details; 3) ends with a concluding sentence. Try to use the unit''s tenses (past perfect / present perfect continuous / future continuous).', '["提出总观点(The idea of \"learning by doing\" is becoming increasingly appealing …)","用亲身经历作支撑细节(In the Art Club, I once …)","用单元时态(had done / have been doing / will be doing)","一句话总结呼应观点"]'::jsonb, 70, 100, 'The idea of "learning by doing" is becoming increasingly appealing to high school students, and my own experience shows why. Last term, I joined a three-dimensional design course in the Art Club. Before that course, I had always thought design was only about computers. To my surprise, we used our hands to fold paper into cranes, lanterns and towers. Each time a structure fell, I learned something new about balance. Since then, I have been telling my friends that we understand an idea best after we try it ourselves. Next month, I will be sharing these projects with our sister school in Singapore.', '【15 分制】A 档(13-15):五要素齐全、组织有条理、语言准确多样;B 档(10-12):要点较全、少量错误;C 档(7-9):要点偏少、句型简单;D 档(0-6):内容不完整、错误多。', '["The idea of \"learning by doing\" is becoming increasingly appealing to high school students.","Before that course, I had always thought design was only about computers.","Each time a structure fell, I learned something new about balance.","We understand an idea best after we try it with our own hands."]'::jsonb, '[{"wrong":"Before the course, I have always thought design was easy.","correct":"Before the course, I had always thought design was easy.","note":"过去某点之前的状态用过去完成时 had thought,不用现在完成时。"},{"wrong":"Since then, I tell my friends about it.","correct":"Since then, I have been telling my friends about it.","note":"since + 持续到现在的动作用现在完成进行时。"},{"wrong":"Next month, I share these projects with our sister school.","correct":"Next month, I will be sharing these projects with our sister school.","note":"将来某时正在进行的动作用将来进行时。"}]'::jsonb, '【做中学网站短文结构】
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content, publisher) VALUES (11, 'elective1', 'U1', '{"title":"三大时态·过去完成时 / 现在完成进行时 / 将来进行时 速查","intro":"本单元三个时态各管一段时间轴:过去完成时=「过去的过去」(had done);现在完成进行时=从过去持续到现在的动作(have been doing);将来进行时=将来某刻正在进行(will be doing)。判断口诀:看时间标志词和「相对哪个时间点」。","table":{"headers":["时态","结构 / 时间标志 / 例句"],"rows":[["过去完成时","had + 过去分词；before / by the time / after / already / by + 过去时间：When I arrived, the class had begun."],["现在完成进行时","have/has been + doing；for / since / all day / lately / recently / how long：She has been studying for hours."],["将来进行时","will be + doing；this time tomorrow / at + 将来时刻 / soon / when you grow up：This time tomorrow I''ll be flying to London."]]},"specialRules":[{"rule":"过去完成时是「过去的过去」——必须有另一个过去动作作参照","mark":"after he had gained his degree, he sailed home"},{"rule":"现在完成进行时强调「动作持续、还可能在继续」,常与 for/since 连用","mark":"Our motherland has been suffering for so long."},{"rule":"将来进行时表示将来某刻「正在进行」,不强调开始或结束","mark":"When you grow up, you will be studying science."},{"rule":"现在完成进行时(强调过程) vs 现在完成时(强调结果):been doing 看重''一直在做'',have done 看重''已做完''","mark":"have been reading(还在读) / have read(读完了)"}],"why":["三个时态都在表达「相对某个时间点」的动作:过去完成相对过去;现在完成进行从过去连到现在;将来进行落在将来。抓住参照点和持续/进行的含义,就不会混。"],"gaokaoPoints":["语法填空高频:by the time / before / after 引导句中辨过去完成时;for / since / lately 辨现在完成进行时。","this time tomorrow / at this moment next week 等标志,辨将来进行时;别误用一般将来时。","完成进行 vs 完成:题干给出 ''and is still doing / 眼睛还红着'' 等线索时,优先 been doing(强调持续)。"],"examVsReal":[{"exam":"By the time we arrived, the film had started.（考试/书面)","real":"We got there late — the film already started.","note":"考试用 had started 体现''过去的过去'';口语里常简化成一般过去时 + already"},{"exam":"I have been studying English for three years.（考试)","real":"I''ve been doing English for three years now.","note":"口语里 study 常说成 do;现在完成进行强调''这些年一直在学''"},{"exam":"This time tomorrow I will be flying to London.（考试)","real":"Same time tomorrow I''ll be on the plane to London.","note":"口语常用 be + 介词短语表''正处于某状态'',意思与将来进行时相近"}]}'::jsonb, 'sufe');
